use vstd::prelude::*;

verus! {

/// Specification for extracting column j (0 <= j < m) from the input matrix.
/// Preconditions:
/// - input has exactly n rows (n > 0),
/// - each row has exactly m columns,
/// - j < m.
/// Ensures:
/// - col is a vector of length n,
/// - for each row index i < n, col[i] == input[i][j].
fn get_column(input: &Vec<Vec<i8>>, j: usize, m: usize, n: usize) -> (col: Vec<i8>)
    requires
        n > 0,
        input.len() == n,
        forall |i: usize| (i < n ==> input[i].len() == m),
        j < m,
    ensures
        col.len() == n,
        forall |i: usize| (i < n ==> col[i] == input[i][j])
{
    let mut col: Vec<i8> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            col.len() == i,
            forall |k: usize| (k < i ==> col[k] == input[k][j]),
        decreases n - i,
    {
        col.push(input[i][j]);
        i += 1;
    }
    col
}

/// Specification for column_stack: transpose the input matrix.
/// Preconditions:
/// - input has exactly n rows (n > 0),
/// - each row has exactly m columns.
/// Ensures:
/// - result has exactly m rows,
/// - each row has exactly n columns,
/// - for all valid i,j indices: result[j][i] = input[i][j],
/// - total number of elements in result is m * n.
fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> (result: Vec<Vec<i8>>)
    requires
        n > 0,
        input.len() == n,
        forall |i: usize| (i < n ==> input[i].len() == m),
    ensures
        result.len() == m,
        forall |j: usize| (j < m ==> result[j].len() == n),
        forall |i: usize, j: usize| (i < n && j < m ==> result[j][i] == input[i][j]),
        result.iter().map(|row| row.len()).sum::<usize>() == m * n
{
    let mut result: Vec<Vec<i8>> = Vec::new();

    let mut j: usize = 0;
    while j < m
        invariant
            j <= m,
            result.len() == j,
            forall |jj: usize| (jj < j ==> result[jj].len() == n &&
                                 forall |ii: usize| ii < n ==> result[jj][ii] == input[ii][jj]),
        decreases m - j,
    {
        // For each column j, extract that column from input as a vector of length n.
        let col = get_column(&input, j, m, n);
        result.push(col);
        j += 1;
    }
    result
}

}
